import pytest
import torch

import flag_gems

from . import accuracy_utils as utils

# Jacobi SVD kernel operates in float32; float16/bfloat16 lack precision for convergence
PINV_DTYPES = [torch.float32]

# Test shapes: (m, n) - square matrices only
# Rectangular matrices have lower SVD precision with fixed Jacobi sweep count
# n <= 8 due to Triton static_range compile time for larger sizes
PINV_SHAPES = [(4, 4), (8, 8)]

# Shapes above the fused kernel's 32-element limit, which route to the blocked
# Jacobi path. Kept small because the reference pinv runs on CPU under --ref=cpu.
PINV_LARGE_SHAPES = [(48, 48), (64, 40), (40, 64)]


def _well_conditioned(m, n, dtype, seed=0):
    """Build a (m, n) matrix with a known, tightly bounded singular spectrum.

    `randn(m, n) + 2 * I` leaves the condition number uncontrolled (observed in
    the hundreds to thousands), and pinv error grows with cond * eps, so that
    construction makes the tolerance check seed-dependent: it passed or failed
    depending on which matrix was drawn. Composing an explicit SVD with
    singular values in [1, 2] pins cond <= 2 instead, for both the fused and
    the blocked kernel paths.
    """
    g = torch.Generator(device="cpu").manual_seed(seed)
    k = min(m, n)
    # Orthonormal factors via QR of fixed-seed gaussians.
    u, _ = torch.linalg.qr(torch.randn(m, k, generator=g))
    v, _ = torch.linalg.qr(torch.randn(n, k, generator=g))
    s = torch.linspace(2.0, 1.0, k)
    A = (u * s) @ v.T
    return A.to(dtype).to(flag_gems.device)


@pytest.mark.linalg_pinv
@pytest.mark.parametrize("shape", PINV_SHAPES)
@pytest.mark.parametrize("dtype", PINV_DTYPES)
def test_linalg_pinv(shape, dtype):
    m, n = shape
    A = _well_conditioned(m, n, dtype)
    ref_A = utils.to_reference(A)
    ref_out = torch.linalg.pinv(ref_A)
    res_out = flag_gems.linalg_pinv(A)
    utils.gems_assert_close(res_out, ref_out, dtype)


@pytest.mark.linalg_pinv
@pytest.mark.parametrize("shape", PINV_SHAPES)
@pytest.mark.parametrize("dtype", PINV_DTYPES)
def test_linalg_pinv_batched(shape, dtype):
    m, n = shape
    batch = 4
    # Distinct seeds so the batch elements are not identical matrices.
    A = torch.stack([_well_conditioned(m, n, dtype, seed=s) for s in range(batch)])
    ref_A = utils.to_reference(A)
    ref_out = torch.linalg.pinv(ref_A)
    res_out = flag_gems.linalg_pinv(A)
    utils.gems_assert_close(res_out, ref_out, dtype)


